<?php session_start();include "config.php";if(!isset($_SESSION["student_id"])){header("Location: login.php");exit;}$sid=(int)$_SESSION["student_id"];
$q=mysqli_prepare($conn,"SELECT r.id,c.course_name,c.duration,c.fees,p.id payment_id,p.payment_status FROM registrations r JOIN courses c ON c.id=r.course_id LEFT JOIN payments p ON p.registration_id=r.id WHERE r.student_id=? ORDER BY r.id DESC");mysqli_stmt_bind_param($q,"i",$sid);mysqli_stmt_execute($q);$res=mysqli_stmt_get_result($q);include "includes/header.php";include "includes/navbar.php";?>
<div class="container py-5"><h2>My Registered Courses</h2><div class="table-responsive mt-4"><table class="table table-hover align-middle bg-white shadow-sm"><thead><tr><th>Course</th><th>Duration</th><th>Fee</th><th>Status</th><th>Bill</th></tr></thead><tbody>
<?php while($r=mysqli_fetch_assoc($res)){?><tr><td><b><?php echo htmlspecialchars($r["course_name"]);?></b></td><td><?php echo htmlspecialchars($r["duration"]);?></td><td>₹<?php echo number_format($r["fees"],2);?></td><td><?php echo $r["payment_status"]?'<span class="badge bg-success">PAID</span>':'<span class="badge bg-warning text-dark">PENDING</span>';?></td><td><?php if($r["payment_id"]) echo '<a href="bill.php?id='.$r["payment_id"].'" class="btn btn-sm btn-primary">View Bill</a>';?></td></tr><?php }?></tbody></table></div></div><?php include "includes/footer.php";?>